"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";

export function CrossfadePrimitive({ stateKey, children }: { stateKey: string; children: ReactNode }) {
  const reduceMotion = useReducedMotion();
  return (
    <AnimatePresence initial={false} mode="sync">
      <motion.div
        key={stateKey}
        initial={reduceMotion ? false : { opacity: 0 }}
        animate={{ opacity: 1, transition: reduceMotion ? { duration: 0.12 } : { duration: 0.2, delay: 0.1, ease: [0.33, 1, 0.68, 1] } }}
        exit={{ opacity: 0, transition: reduceMotion ? { duration: 0.12 } : { duration: 0.2, ease: [0.33, 1, 0.68, 1] } }}
      >
        {children}
      </motion.div>
    </AnimatePresence>
  );
}
